MATCH p=(a:Issue)-[rs*1..5]-(b:Issue)
WHERE all(r IN rs WHERE NOT type(r) IN ['HAS_PARENT','IN_PROJECT','ASSIGNED_TO','REPORTED_BY','CREATED_BY','FIXED_IN','LOGGED_TIME'] AND exists{(startNode(r))-[:ASSIGNED_TO]->(x) MATCH (endNode(r))-[:ASSIGNED_TO]->(y) WHERE x<>y})
AND size(nodes(p))=size(apoc.coll.toSet(nodes(p)))
AND NOT exists{(a)-[r2]-(c:Issue) WHERE NOT c IN nodes(p) AND NOT type(r2) IN ['HAS_PARENT','IN_PROJECT','ASSIGNED_TO','REPORTED_BY','CREATED_BY','FIXED_IN','LOGGED_TIME'] AND exists{(a)-[:ASSIGNED_TO]->(x) MATCH (c)-[:ASSIGNED_TO]->(y) WHERE x<>y}}
AND NOT exists{(b)-[r2]-(c:Issue) WHERE NOT c IN nodes(p) AND NOT type(r2) IN ['HAS_PARENT','IN_PROJECT','ASSIGNED_TO','REPORTED_BY','CREATED_BY','FIXED_IN','LOGGED_TIME'] AND exists{(b)-[:ASSIGNED_TO]->(x) MATCH (c)-[:ASSIGNED_TO]->(y) WHERE x<>y}}
RETURN [n IN nodes(p)|n.issueKey] AS path, [r IN rs|r.linkId] AS links

MATCH p=(a:Issue)((x:Issue)-[r]-(y:Issue) WHERE r.linkId IS NOT NULL AND head([(x)-[:ASSIGNED_TO]->(u)|u.personKey]) <> head([(y)-[:ASSIGNED_TO]->(v)|v.personKey])){1,5}(b:Issue)
WITH p, a, b, nodes(p) AS ns, relationships(p) AS rs
WHERE all(i IN range(0,size(ns)-1) WHERE all(j IN range(i+1,size(ns)-1) WHERE ns[i]<>ns[j]))
AND NOT exists{(a)-[r2]-(c:Issue) WHERE r2.linkId IS NOT NULL AND NOT c IN ns AND head([(c)-[:ASSIGNED_TO]->(y)|y.personKey]) IS NOT NULL AND head([(c)-[:ASSIGNED_TO]->(y)|y.personKey])<>head([(a)-[:ASSIGNED_TO]->(z)|z.personKey])}
AND NOT exists{(b)-[r2]-(c:Issue) WHERE r2.linkId IS NOT NULL AND NOT c IN ns AND head([(c)-[:ASSIGNED_TO]->(y)|y.personKey]) IS NOT NULL AND head([(c)-[:ASSIGNED_TO]->(y)|y.personKey])<>head([(b)-[:ASSIGNED_TO]->(z)|z.personKey])}
RETURN [n IN ns|n.issueKey] AS path, [r IN rs|r.linkId] AS links, [n IN ns|n.issueKey] AS issues

MATCH p=(a:Issue)((x:Issue)-[r]-(y:Issue) WHERE r.linkId IS NOT NULL AND head([(x)-[:ASSIGNED_TO]->(u)|u.personKey]) <> head([(y)-[:ASSIGNED_TO]->(v)|v.personKey])){1,5}(b:Issue)
