AND NOT exists{(a)-[r2]-(c:Issue) WHERE r2.linkId IS NOT NULL AND NOT c IN ns AND head([(c)-[:ASSIGNED_TO]->(k)|k.personKey]) IS NOT NULL AND head([(c)-[:ASSIGNED_TO]->(k)|k.personKey])<>head([(a)-[:ASSIGNED_TO]->(m)|m.personKey])}
AND NOT exists{(b)-[r3]-(d:Issue) WHERE r3.linkId IS NOT NULL AND NOT d IN ns AND head([(d)-[:ASSIGNED_TO]->(k)|k.personKey]) IS NOT NULL AND head([(d)-[:ASSIGNED_TO]->(k)|k.personKey])<>head([(b)-[:ASSIGNED_TO]->(m)|m.personKey])}
RETURN [n IN ns|n.issueKey] AS path, [i IN range(0,size(rs)-1)|[ns[i].issueKey, ns[i+1].issueKey]] AS issue, [r IN rs|r.linkId] AS issue_link
